+import { z } from "zod";
+import type { UpdateUserResponse } from "../plugins/custom-endpoints.plugin";
+
+/**
+ * Update User Endpoint Handler
+ * 
+ * POST /api/auth/update-user
+ * 
+ * Updates the current user's profile information.
+ * Requires active session (authenticated request).
+ * 
+ * @param ctx - Better Auth context with adapter and session
+ * @param body - { name?: string, email?: string, image?: string | null }
+ * @returns {UpdateUserResponse} Updated user data
+ */
+
+const UpdateUserSchema = z.object({
+  name: z.string().min(2, "Name must be at least 2 characters").optional(),
+  email: z.string().email("Invalid email address").optional(),
+  image: z.string().url("Invalid image URL").optional().nullable(),
+});
+
+export async function updateUserHandler(ctx: any): Promise<UpdateUserResponse> {
+  const session = ctx.context.session;
+  
+  if (!session) {
+    throw new Error("Not authenticated");
+  }
+
+  try {
+    const body = ctx.request.body 
+      ? (typeof ctx.request.body === "string" 
+          ? JSON.parse(ctx.request.body) 
+          : ctx.request.body)
+      : {};
+
+    const validatedData = UpdateUserSchema.parse(body);
+
+    // If email is being updated, check if it's already taken
+    if (validatedData.email && validatedData.email !== session.user.email) {
+      const existingUser = await ctx.context.adapter.findUserByEmail(
+        validatedData.email
+      );
+      
+      if (existingUser) {
+        throw new Error("Email is already in use");
+      }
+    }
+
+    // Prepare update data
+    const updateData: any = {};
+    if (validatedData.name) updateData.name = validatedData.name;
+    if (validatedData.email) updateData.email = validatedData.email;
+    if (validatedData.image !== undefined) updateData.image = validatedData.image;
+    updateData.updatedAt = new Date();
+
+    // Update user in database
+    const updated = await ctx.context.adapter.updateUser(
+      session.user.id,
+      updateData
+    );
+
+    return {
+      success: true,
+      user: {
+        id: updated.id,
+        name: updated.name,
+        email: updated.email,
+        image: updated.image || null,
+        updatedAt: updated.updatedAt || new Date(),
+      },
+    };
+  } catch (error) {
+    if (error instanceof z.ZodError) {
+      throw new Error(`Validation failed: ${error.errors[0].message}`);
+    }
+    throw error;
+  }
+}

