import { randomUUID } from "crypto";
import type { TUserId, TSessionId, TAccountId, TVerificationId, TTokenId } from "@/types/id.types";

/**
 * ID Generator - Creates branded IDs for type safety
 */
export const ID = {
  /**
   * Generate a new user ID
   */
  user(): TUserId {
    return randomUUID() as TUserId;
  },

  /**
   * Generate a new session ID
   */
  session(): TSessionId {
    return randomUUID() as TSessionId;
  },

  /**
   * Generate a new account ID
   */
  account(): TAccountId {
    return randomUUID() as TAccountId;
  },

  /**
   * Generate a new verification ID
   */
  verification(): TVerificationId {
    return randomUUID() as TVerificationId;
  },

  /**
   * Generate a new token ID
   */
  token(): TTokenId {
    return randomUUID() as TTokenId;
  },
};

import type { BetterAuthOptions } from "better-auth";
import type { TUserId } from "@/types/id.types";
import { z } from "zod";

/**
 * Custom Endpoints Plugin for Better Auth
 * 
 * Adds three custom endpoints:
 * - GET /get-session - Fetch current user session with full user info
 * - POST /update-user - Update user profile (name, email, image)
 * - POST /custom-sign-up - Custom sign-up with validation using branded IDs
 * 
 * This plugin uses Better Auth's hook system to intercept and handle
 * requests before they reach the standard endpoints.
 */

// Request/Response schemas
export const GetSessionSchema = z.object({});

export const UpdateUserSchema = z.object({
  name: z.string().optional(),
  email: z.string().email().optional(),
  image: z.string().url().optional().nullable(),
});

export const CustomSignUpSchema = z.object({
  email: z.string().email("Invalid email address"),
  password: z.string().min(8, "Password must be at least 8 characters"),
  name: z.string().min(2, "Name must be at least 2 characters"),
  confirmPassword: z.string().min(8),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

export type GetSessionRequest = z.infer<typeof GetSessionSchema>;
export type UpdateUserRequest = z.infer<typeof UpdateUserSchema>;
export type CustomSignUpRequest = z.infer<typeof CustomSignUpSchema>;

/**
 * Custom Endpoints Response Types
 */
export interface GetSessionResponse {
  session: {
    id: string;
    userId: string;
    expiresAt: Date;
    createdAt: Date;
    updatedAt: Date;
  } | null;
  user: {
    id: string;
    name: string;
    email: string;
    image: string | null;
    emailVerified: boolean;
    createdAt: Date;
    updatedAt: Date;
  } | null;
}

export interface UpdateUserResponse {
  success: boolean;
  user: {
    id: string;
    name: string;
    email: string;
    image: string | null;
    updatedAt: Date;
  };
}

export interface CustomSignUpResponse {
  success: boolean;
  user?: {
    id: string;
    email: string;
    name: string;
    emailVerified: boolean;
  };
  session?: {
    id: string;
    expiresAt: Date;
  };
}

/**
 * Create the custom endpoints plugin
 * 
 * This plugin adds custom request handlers via Better Auth's hook system
 */
export function customEndpointsPlugin(): Partial<BetterAuthOptions> {
  return {
    // Custom hooks to handle additional endpoints
    hooks: {
      before: [
        {
          matcher: (ctx) => ctx.path === "/get-session",
          handler: async (ctx) => {
            // Get session from context
            const session = ctx.context.session;

            if (!session) {
              ctx.context.returned = {
                status: 401,
                body: { error: "Not authenticated" },
              };
              return;
            }

            // Fetch full user data from database
            const userInDb = await ctx.context.adapter.findUserByEmail(
              session.user.email
            );

            ctx.context.returned = {
              status: 200,
              body: {
                session: {
                  id: session.id,
                  userId: session.userId,
                  expiresAt: session.expiresAt,
                  createdAt: session.createdAt,
                  updatedAt: session.updatedAt || new Date(),
                },
                user: userInDb ? {
                  id: userInDb.id,
                  name: userInDb.name,
                  email: userInDb.email,
                  image: userInDb.image || null,
                  emailVerified: userInDb.emailVerified,
                  createdAt: userInDb.createdAt,
                  updatedAt: userInDb.updatedAt,
                } : null,
              } as GetSessionResponse,
            };
          },
        },
        {
          matcher: (ctx) => ctx.path === "/update-user" && ctx.method === "POST",
          handler: async (ctx) => {
            const session = ctx.context.session;

            if (!session) {
              ctx.context.returned = {
                status: 401,
                body: { error: "Not authenticated" },
              };
              return;
            }

            try {
              const body = ctx.request.body 
                ? (typeof ctx.request.body === "string" 
                    ? JSON.parse(ctx.request.body) 
                    : ctx.request.body)
                : {};

              const validatedData = UpdateUserSchema.parse(body);

              // Update user in database
              const updateData: any = {};
              if (validatedData.name) updateData.name = validatedData.name;
              if (validatedData.email) updateData.email = validatedData.email;
              if (validatedData.image !== undefined) updateData.image = validatedData.image;
              if (validatedData.email) updateData.updatedAt = new Date();

              const updated = await ctx.context.adapter.updateUser(
                session.user.id,
                updateData
              );

              ctx.context.returned = {
                status: 200,
                body: {
                  success: true,
                  user: {
                    id: updated.id,
                    name: updated.name,
                    email: updated.email,
                    image: updated.image || null,
                    updatedAt: updated.updatedAt || new Date(),
                  },
                } as UpdateUserResponse,
              };
            } catch (error) {
              ctx.context.returned = {
                status: 400,
                body: {
                  success: false,
                  error: error instanceof Error ? error.message : "Invalid request",
                },
              };
            }
          },
        },
        {
          matcher: (ctx) => ctx.path === "/custom-sign-up" && ctx.method === "POST",
          handler: async (ctx) => {
            try {
              const body = ctx.request.body 
                ? (typeof ctx.request.body === "string" 
                    ? JSON.parse(ctx.request.body) 
                    : ctx.request.body)
                : {};

              const validatedData = CustomSignUpSchema.parse(body);

              // Check if user already exists
              const existingUser = await ctx.context.adapter.findUserByEmail(
                validatedData.email
              );

              if (existingUser) {
                ctx.context.returned = {
                  status: 409,
                  body: {
                    success: false,
                    error: "User with this email already exists",
                  },
                };
                return;
              }

              // Hash password
              const hashedPassword = await ctx.context.password.hash(
                validatedData.password
              );

              // Create user with branded ID
              const user = await ctx.context.adapter.createUser({
                email: validatedData.email,
                name: validatedData.name,
                emailVerified: false,
              });

              // Create account with password
              await ctx.context.adapter.createAccount({
                userId: user.id,
                providerId: "credential",
                providerAccountId: validatedData.email,
                password: hashedPassword,
                accessToken: null,
                accessTokenExpiresAt: null,
                refreshToken: null,
                refreshTokenExpiresAt: null,
                idToken: null,
                scope: null,
              });

              // Create session
              const sessionData = {
                userId: user.id,
                expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7 days
                token: ctx.context.generateId(),
              };

              const session = await ctx.context.adapter.createSession(sessionData);

              ctx.context.returned = {
                status: 201,
                body: {
                  success: true,
                  user: {
                    id: user.id,
                    email: user.email,
                    name: user.name,
                    emailVerified: user.emailVerified,
                  },
                  session: {
                    id: session.id,
                    expiresAt: session.expiresAt,
                  },
                } as CustomSignUpResponse,
              };
            } catch (error) {
              if (error instanceof z.ZodError) {
                ctx.context.returned = {
                  status: 400,
                  body: {
                    success: false,
                    error: "Validation failed",
                    details: error.errors,
                  },
                };
              } else {
                ctx.context.returned = {
                  status: 500,
                  body: {
                    success: false,
                    error: error instanceof Error ? error.message : "Sign up failed",
                  },
                };
              }
            }
          },
        },
      ],
    },
  };
}

import type { GetSessionResponse } from "../plugins/custom-endpoints.plugin";

/**
 * Get Session Endpoint Handler
 * 
 * GET /api/auth/get-session
 * 
 * Retrieves the current user's session and full profile information.
 * Requires active session (authenticated request).
 * 
 * @returns {GetSessionResponse} Session and user data
 */
export async function getSessionHandler(ctx: any): Promise<GetSessionResponse> {
  const session = ctx.context.session;

  if (!session) {
    throw new Error("Not authenticated");
  }

  // Fetch full user data from database
  const userInDb = await ctx.context.adapter.findUserByEmail(
    session.user.email
  );

  return {
    session: {
      id: session.id,
      userId: session.userId,
      expiresAt: session.expiresAt,
      createdAt: session.createdAt,
      updatedAt: session.updatedAt || new Date(),
    },
    user: userInDb ? {
      id: userInDb.id,
      name: userInDb.name,
      email: userInDb.email,
      image: userInDb.image || null,
      emailVerified: userInDb.emailVerified,
      createdAt: userInDb.createdAt,
      updatedAt: userInDb.updatedAt,
    } : null,
  };
}

import { z } from "zod";
import type { UpdateUserResponse } from "../plugins/custom-endpoints.plugin";

/**
 * Update User Endpoint Handler
 * 
 * POST /api/auth/update-user
 * 
 * Updates the current user's profile information.
 * Requires active session (authenticated request).
 * 
 * @param ctx - Better Auth context with adapter and session
 * @param body - { name?: string, email?: string, image?: string | null }
 * @returns {UpdateUserResponse} Updated user data
 */

const UpdateUserSchema = z.object({
  name: z.string().min(2, "Name must be at least 2 characters").optional(),
  email: z.string().email("Invalid email address").optional(),
  image: z.string().url("Invalid image URL").optional().nullable(),
});

export async function updateUserHandler(ctx: any): Promise<UpdateUserResponse> {
  const session = ctx.context.session;

  if (!session) {
    throw new Error("Not authenticated");
  }

  try {
    const body = ctx.request.body 
      ? (typeof ctx.request.body === "string" 
          ? JSON.parse(ctx.request.body) 
          : ctx.request.body)
      : {};

    const validatedData = UpdateUserSchema.parse(body);

    // If email is being updated, check if it's already taken
    if (validatedData.email && validatedData.email !== session.user.email) {
      const existingUser = await ctx.context.adapter.findUserByEmail(
        validatedData.email
      );

      if (existingUser) {
        throw new Error("Email is already in use");
      }
    }

    // Prepare update data
    const updateData: any = {};
    if (validatedData.name) updateData.name = validatedData.name;
    if (validatedData.email) updateData.email = validatedData.email;
    if (validatedData.image !== undefined) updateData.image = validatedData.image;
    updateData.updatedAt = new Date();

    // Update user in database
    const updated = await ctx.context.adapter.updateUser(
      session.user.id,
      updateData
    );

    return {
      success: true,
      user: {
        id: updated.id,
        name: updated.name,
        email: updated.email,
        image: updated.image || null,
        updatedAt: updated.updatedAt || new Date(),
      },
    };
  } catch (error) {
    if (error instanceof z.ZodError) {
      throw new Error(`Validation failed: ${error.errors[0].message}`);
    }
    throw error;
  }
}

import { z } from "zod";
import { ID } from "../utils/ID";
import type { CustomSignUpResponse } from "../plugins/custom-endpoints.plugin";

/**
 * Custom Sign-Up Endpoint Handler
 * 
 * POST /api/auth/custom-sign-up
 * 
 * Creates a new user account with email/password authentication.
 * Uses branded ID types for type safety.
 * Automatically creates a session upon successful registration.
 * 
 * @param ctx - Better Auth context with adapter
 * @param body - { email: string, password: string, name: string, confirmPassword: string }
 * @returns {CustomSignUpResponse} New user and session data
 */

const CustomSignUpSchema = z.object({
  email: z.string().email("Invalid email address"),
  password: z.string().min(8, "Password must be at least 8 characters"),
  name: z.string().min(2, "Name must be at least 2 characters"),
  confirmPassword: z.string().min(8),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

export async function customSignUpHandler(ctx: any): Promise<CustomSignUpResponse> {
  try {
    const body = ctx.request.body 
      ? (typeof ctx.request.body === "string" 
          ? JSON.parse(ctx.request.body) 
          : ctx.request.body)
      : {};

    const validatedData = CustomSignUpSchema.parse(body);

    // Check if user already exists
    const existingUser = await ctx.context.adapter.findUserByEmail(
      validatedData.email
    );

    if (existingUser) {
      throw new Error("User with this email already exists");
    }

    // Create user with branded ID (using custom ID generator)
    const userId = ID.user();

    const user = await ctx.context.adapter.createUser({
      id: userId,
      email: validatedData.email,
      name: validatedData.name,
      emailVerified: false,
    });

    // Hash password
    const hashedPassword = await ctx.context.password.hash(
      validatedData.password
    );

    // Create account with password provider
    const accountId = ID.account();

    await ctx.context.adapter.createAccount({
      id: accountId,
      userId: user.id,
      providerId: "credential",
      providerAccountId: validatedData.email,
      password: hashedPassword,
      accessToken: null,
      accessTokenExpiresAt: null,
      refreshToken: null,
      refreshTokenExpiresAt: null,
      idToken: null,
      scope: null,
    });

    // Create session with branded ID
    const sessionId = ID.session();
    const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000); // 7 days

    const session = await ctx.context.adapter.createSession({
      id: sessionId,
      userId: user.id,
      expiresAt,
      token: ID.token(),
      ipAddress: ctx.request.ip || undefined,
      userAgent: ctx.request.headers?.["user-agent"] || undefined,
    });

    return {
      success: true,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        emailVerified: user.emailVerified,
      },
      session: {
        id: session.id,
        expiresAt: session.expiresAt,
      },
    };
  } catch (error) {
    if (error instanceof z.ZodError) {
      throw new Error(`Validation failed: ${error.errors[0].message}`);
    }
    throw error;
  }
}

