import { betterAuth } from "better-auth";
import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import { config } from "@env";
import { db } from "@/modules/database/client";
import { openAPI } from "better-auth/plugins";
import { customEndpointsPlugin } from "@/modules/auth";

/**
 * Better Auth Configuration
 * 
 * Configured with:
 * - Drizzle ORM adapter for PostgreSQL
 * - Email/password authentication
 * - 7-day session expiry with hourly refresh
 * - Custom endpoints plugin for enhanced functionality:
 *   - GET /get-session - Fetch current session with full user data
 *   - POST /update-user - Update user profile
 *   - POST /custom-sign-up - Custom sign-up with validation
 * - OpenAPI documentation plugin
 * 
 * See: https://better-auth.com/docs
 */
export const auth = betterAuth({
  database: drizzleAdapter(db, {
    provider: "pg",
    camelCase: true,
    transaction: true,
    debugLogs: config.env === "development",
    usePlural: true,
  }),
  plugins: [
    openAPI(),
    customEndpointsPlugin(),
  ],
  secret: process.env.BETTER_AUTH_SECRET,
  baseURL: process.env.BETTER_AUTH_URL,
  basePath: "/api/auth",
  appName: "Wave",

  emailAndPassword: {
    enabled: true,
    requireEmailVerification: false, // Set to true in production
    minPasswordLength: 8,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 7, // 7 days
    updateAge: 60 * 60, // Update age every hour
    cookieCache: {
      enabled: true,
      maxAge: 5 * 60, // 5 minutes
    },
  },

  advanced: {
    useSecureCookies: process.env.NODE_ENV === "production",
    disableCSRFCheck: false,
  },

  trustedOrigins: [
    "http://localhost:3000",
    "http://localhost:3001",
  ],

});

export type Session = typeof auth.$Infer.Session;
export type User = typeof auth.$Infer.Session.user;

import type { FastifyInstance } from "fastify";
import { auth } from "@/lib/auth";

/**
 * Better Auth Route Handler
 * 
 * Registers all Better Auth endpoints at /api/auth/*
 * 
 * Better Auth handles:
 * - POST /api/auth/sign-up - Email/password registration
 * - POST /api/auth/sign-in - Email/password login
 * - POST /api/auth/sign-out - Logout
 * - GET /api/auth/session - Get current session
 * - GET /api/auth/get-session - Custom endpoint (full session + user data)
 * - POST /api/auth/update-user - Custom endpoint (update user profile)
 * - POST /api/auth/custom-sign-up - Custom endpoint (custom sign-up)
 * - And many more...
 * 
 * See: https://better-auth.com/docs/reference/client-side-methods
 */
export default async function authRoutes(fastify: FastifyInstance) {
  // Catch all routes with wildcard pattern
  fastify.all<{ Params: { "*": string } }>("/*", async (request, reply) => {
    try {
      // Build the full URL for Better Auth
      const url = new URL(
        `${request.protocol}://${request.hostname}/api/auth/${request.params["*"]}`
      );

      // Prepare request body
      const body = ["GET", "HEAD"].includes(request.method)
        ? undefined
        : request.body instanceof Buffer
          ? request.body
          : request.body
            ? JSON.stringify(request.body)
            : undefined;

      // Call Better Auth handler
      const response = await auth.handler(
        new Request(url, {
          method: request.method,
          headers: request.headers as HeadersInit,
          body,
        })
      );

      // Copy all response headers
      response.headers.forEach((value, key) => {
        reply.header(key, value);
      });

      // Send response with correct status code
      reply.status(response.status);

      // Parse and send response body
      const contentType = response.headers.get("content-type");
      if (contentType?.includes("application/json")) {
        try {
          return reply.send(await response.json());
        } catch {
          return reply.send(await response.text());
        }
      }

      return reply.send(await response.text());
    } catch (error) {
      fastify.log.error(error);
      reply.status(500);
      return reply.send({ error: "Internal server error" });
    }
  });
}

