import type { BetterAuthOptions } from "better-auth";
import { z } from "zod";

/**
 * Custom Endpoints Plugin for Better Auth
 * 
 * Adds three custom endpoints:
 * - GET /get-session - Fetch current user session with full user info
 * - POST /update-user - Update user profile (name, email, image)
 * - POST /custom-sign-up - Custom sign-up with validation using branded IDs
 * 
 * This plugin uses Better Auth's hook system to intercept and handle
 * requests before they reach the standard endpoints.
 */

// Request/Response schemas
export const GetSessionSchema = z.object({});

export const UpdateUserSchema = z.object({
  name: z.string().optional(),
  email: z.string().email().optional(),
  image: z.string().url().optional().nullable(),
});

export const CustomSignUpSchema = z.object({
  email: z.string().email("Invalid email address"),
  password: z.string().min(8, "Password must be at least 8 characters"),
  name: z.string().min(2, "Name must be at least 2 characters"),
  confirmPassword: z.string().min(8),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

export type GetSessionRequest = z.infer<typeof GetSessionSchema>;
export type UpdateUserRequest = z.infer<typeof UpdateUserSchema>;
export type CustomSignUpRequest = z.infer<typeof CustomSignUpSchema>;

/**
 * Custom Endpoints Response Types
 */
export interface GetSessionResponse {
  session: {
    id: string;
    userId: string;
    expiresAt: Date;
    createdAt: Date;
    updatedAt: Date;
  } | null;
  user: {
    id: string;
    name: string;
    email: string;
    image: string | null;
    emailVerified: boolean;
    createdAt: Date;
    updatedAt: Date;
  } | null;
}

export interface UpdateUserResponse {
  success: boolean;
  user: {
    id: string;
    name: string;
    email: string;
    image: string | null;
    updatedAt: Date;
  };
}

export interface CustomSignUpResponse {
  success: boolean;
  user?: {
    id: string;
    email: string;
    name: string;
    emailVerified: boolean;
  };
  session?: {
    id: string;
    expiresAt: Date;
  };
}

/**
 * Create the custom endpoints plugin
 * 
 * This plugin adds custom request handlers via Better Auth's hook system
 */
export function customEndpointsPlugin(): Partial<BetterAuthOptions> {
  return {
    // Custom hooks to handle additional endpoints
    hooks: {
      before: [
        {
          matcher: (ctx: any) => ctx.path === "/get-session",
          handler: async (ctx: any) => {
            try {
              // Get session from context
              const session = ctx.context.session;

              if (!session) {
                ctx.context.returned = {
                  status: 401,
                  body: { error: "Not authenticated" },
                };
                return;
              }

              // Fetch full user data from database
              const userInDb = await ctx.context.adapter.findUserByEmail(
                session.user.email
              );

              ctx.context.returned = {
                status: 200,
                body: {
                  session: {
                    id: session.id,
                    userId: session.userId,
                    expiresAt: session.expiresAt,
                    createdAt: session.createdAt,
                    updatedAt: session.updatedAt || new Date(),
                  },
                  user: userInDb ? {
                    id: userInDb.id,
                    name: userInDb.name,
                    email: userInDb.email,
                    image: userInDb.image || null,
                    emailVerified: userInDb.emailVerified,
                    createdAt: userInDb.createdAt,
                    updatedAt: userInDb.updatedAt,
                  } : null,
                } as GetSessionResponse,
              };
            } catch (error: unknown) {
              ctx.context.returned = {
                status: 500,
                body: {
                  error: error instanceof Error ? error.message : "Failed to fetch session",
                },
              };
            }
          },
        },
        {
          matcher: (ctx: any) => ctx.path === "/update-user" && ctx.method === "POST",
          handler: async (ctx: any) => {
            try {
              const session = ctx.context.session;

              if (!session) {
                ctx.context.returned = {
                  status: 401,
                  body: { error: "Not authenticated" },
                };
                return;
              }

              const body = ctx.request?.body 
                ? (typeof ctx.request.body === "string" 
                    ? JSON.parse(ctx.request.body) 
                    : ctx.request.body)
                : {};

              const validatedData = UpdateUserSchema.parse(body);

              // Update user in database
              const updateData: Record<string, unknown> = {};
              if (validatedData.name) updateData.name = validatedData.name;
              if (validatedData.email) updateData.email = validatedData.email;
              if (validatedData.image !== undefined) updateData.image = validatedData.image;
              if (Object.keys(updateData).length > 0) {
                updateData.updatedAt = new Date();
              }

              const updated = await ctx.context.adapter.updateUser(
                session.user.id,
                updateData
              );

              ctx.context.returned = {
                status: 200,
                body: {
                  success: true,
                  user: {
                    id: updated.id,
                    name: updated.name,
                    email: updated.email,
                    image: updated.image || null,
                    updatedAt: updated.updatedAt || new Date(),
                  },
                } as UpdateUserResponse,
              };
            } catch (error: unknown) {
              if (error instanceof z.ZodError) {
                ctx.context.returned = {
                  status: 400,
                  body: {
                    success: false,
                    error: "Validation failed",
                    details: error.errors.map(e => ({
                      path: e.path.join("."),
                      message: e.message,
                    })),
                  },
                };
              } else {
                ctx.context.returned = {
                  status: 400,
                  body: {
                    success: false,
                    error: error instanceof Error ? error.message : "Invalid request",
                  },
                };
              }
            }
          },
        },
        {
          matcher: (ctx: any) => ctx.path === "/custom-sign-up" && ctx.method === "POST",
          handler: async (ctx: any) => {
            try {
              const body = ctx.request?.body 
                ? (typeof ctx.request.body === "string" 
                    ? JSON.parse(ctx.request.body) 
                    : ctx.request.body)
                : {};

              const validatedData = CustomSignUpSchema.parse(body);

              // Check if user already exists
              const existingUser = await ctx.context.adapter.findUserByEmail(
                validatedData.email
              );

              if (existingUser) {
                ctx.context.returned = {
                  status: 409,
                  body: {
                    success: false,
                    error: "User with this email already exists",
                  },
                };
                return;
              }

              // Hash password
              const hashedPassword = await ctx.context.password.hash(
                validatedData.password
              );

              // Create user
              const user = await ctx.context.adapter.createUser({
                email: validatedData.email,
                name: validatedData.name,
                emailVerified: false,
              });

              // Create account with password
              await ctx.context.adapter.createAccount({
                userId: user.id,
                providerId: "credential",
                providerAccountId: validatedData.email,
                password: hashedPassword,
                accessToken: null,
                accessTokenExpiresAt: null,
                refreshToken: null,
                refreshTokenExpiresAt: null,
                idToken: null,
                scope: null,
              });

              // Create session
