import { betterAuth } from "better-auth";
import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import { config } from "@env";
import { db } from "@/modules/database/client";
import { openAPI } from "better-auth/plugins";
import { customEndpointsPlugin } from "@/modules/auth";

/**
 * Better Auth Configuration
 * 
 * Configured with:
 * - Drizzle ORM adapter for PostgreSQL
 * - Email/password authentication
 * - 7-day session expiry with hourly refresh
 * - Custom endpoints plugin for enhanced functionality:
 *   - GET /get-session - Fetch current session with full user data
 *   - POST /update-user - Update user profile
 *   - POST /custom-sign-up - Custom sign-up with validation
 * - OpenAPI documentation plugin
 * - CSRF bypass for custom endpoints
 * 
 * See: https://better-auth.com/docs
 */
export const auth = betterAuth({
  database: drizzleAdapter(db, {
    provider: "pg",
    camelCase: true,
    transaction: true,
    debugLogs: config.env === "development",
    usePlural: true,
  }),
  plugins: [
    openAPI(),
    customEndpointsPlugin(),
  ],
  secret: process.env.BETTER_AUTH_SECRET,
  baseURL: process.env.BETTER_AUTH_URL,
  basePath: "/api/auth",
  appName: "Wave",

  emailAndPassword: {
    enabled: true,
    requireEmailVerification: false, // Set to true in production
    minPasswordLength: 8,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 7, // 7 days
    updateAge: 60 * 60, // Update age every hour
    cookieCache: {
      enabled: true,
      maxAge: 5 * 60, // 5 minutes
    },
  },

  advanced: {
    useSecureCookies: process.env.NODE_ENV === "production",
    disableCSRFCheck: false,
    // Bypass CSRF checks for custom endpoints
    skipCSRFCheckForPath: [
