              // Bypass CSRF check for this endpoint
              ctx.context.csrfVerified = true;

              const session = ctx.context.session;

              if (!session) {
                ctx.context.returned = {
                  status: 401,
                  body: { error: "Not authenticated" },
                };
                return;
              }

              const body = ctx.request?.body 
                ? (typeof ctx.request.body === "string" 
                    ? JSON.parse(ctx.request.body) 
                    : ctx.request.body)
                : {};

              const validatedData = UpdateUserSchema.parse(body);

              // Check if email is being updated and already taken
              if (validatedData.email && validatedData.email !== session.user.email) {
                const existingUser = await ctx.context.adapter.findUserByEmail(
                  validatedData.email
                );
                if (existingUser) {
                  ctx.context.returned = {
                    status: 409,
                    body: { error: "Email already in use" },
                  };
                  return;
                }
              }

              // Update user in database
              const updateData: Record<string, unknown> = {};
              if (validatedData.name) updateData.name = validatedData.name;
              if (validatedData.email) updateData.email = validatedData.email;
              if (validatedData.image !== undefined) updateData.image = validatedData.image;
