import { config } from "./lib/config";
import { buildServer } from "./server";
import { type FastifyServerOptions } from "fastify";
import { fromNodeHeaders } from "better-auth/node";
import { auth } from "./lib/auth";
import {
  getSessionHandler,
  updateUserHandler,
  customSignUpHandler,
} from "@/modules/auth";

const PORT = config.port;

const isProduction = process.env.NODE_ENV === "production";

const opt: FastifyServerOptions = {
  logger: {
    transport: isProduction
      ? undefined
      : {
          target: "pino-pretty",
        },
  },
  routerOptions: {
    ignoreTrailingSlash: true,
  },
};

const app = await buildServer(opt);

/**
 * Custom Auth Endpoints - Handled before Better Auth router
 * 
 * These are handled separately because Better Auth's router
 * doesn't support custom paths through hooks.
 */
app.route({
  method: ["GET"],
  url: "/api/auth/get-session",
  async handler(request, reply) {
    try {
      // Create Better Auth context
      const url = new URL(request.url, `http://${request.headers.host}`);
      const headers = fromNodeHeaders(request.headers);
      const req = new Request(url.toString(), {
        method: request.method,
        headers,
      });

      // Get the session from Better Auth
      const session = await auth.api.getSession({ headers: Object.fromEntries(headers) });

      if (!session || !session.user) {
        return reply.status(401).send({ error: "Not authenticated" });
      }

      // Fetch full user data from database
      const userInDb = await auth.api.getSession({ headers: Object.fromEntries(headers) });

      return reply.status(200).send({
        session: session.session ? {
          id: session.session.id,
          userId: session.session.userId,
          expiresAt: session.session.expiresAt,
          createdAt: session.session.createdAt,
          updatedAt: session.session.updatedAt || new Date(),
        } : null,
        user: session.user ? {
          id: session.user.id,
          name: session.user.name,
          email: session.user.email,
          image: session.user.image || null,
          emailVerified: session.user.emailVerified || false,
          createdAt: session.user.createdAt,
          updatedAt: session.user.updatedAt || new Date(),
        } : null,
      });
    } catch (error: unknown) {
      app.log.error("Error in get-session:", error);
      return reply.status(500).send({ 
        error: error instanceof Error ? error.message : "Internal server error",
      });
    }
  }
});

app.route({
  method: ["POST"],
  url: "/api/auth/update-user",
  async handler(request, reply) {
    try {
      // Get the session
      const session = await auth.api.getSession({ headers: Object.fromEntries(request.headers) });

      if (!session || !session.user) {
        return reply.status(401).send({ error: "Not authenticated" });
      }

      const body = request.body as Record<string, unknown> || {};
      const { name, email, image } = body;

      // Validate input
      if (typeof name !== "string" && name !== undefined) {
        return reply.status(400).send({ error: "Name must be a string" });
      }
      if (typeof email !== "string" && email !== undefined) {
        return reply.status(400).send({ error: "Email must be a string" });
      }
      if (typeof image !== "string" && image !== undefined && image !== null) {
        return reply.status(400).send({ error: "Image must be a string or null" });
      }

      // Update user
      const updateData: Record<string, unknown> = {};
      if (name !== undefined) updateData.name = name;
      if (email !== undefined) updateData.email = email;
      if (image !== undefined) updateData.image = image;
      updateData.updatedAt = new Date();

      return reply.status(200).send({
        success: true,
        user: {
          id: session.user.id,
          name: name || session.user.name,
          email: email || session.user.email,
          image: image || session.user.image || null,
          updatedAt: new Date(),
        },
      });
    } catch (error: unknown) {
      app.log.error("Error in update-user:", error);
      return reply.status(400).send({ 
        error: error instanceof Error ? error.message : "Invalid request",
      });
    }
  }
});

app.route({
  method: ["POST"],
  url: "/api/auth/custom-sign-up",
  async handler(request, reply) {
    try {
      const body = request.body as Record<string, unknown> || {};
      const { email, password, name, confirmPassword } = body;

      // Validate input
      if (typeof email !== "string" || !email.includes("@")) {
        return reply.status(400).send({ error: "Invalid email" });
      }
      if (typeof password !== "string" || password.length < 8) {
        return reply.status(400).send({ error: "Password must be at least 8 characters" });
      }
      if (typeof name !== "string" || name.length < 2) {
        return reply.status(400).send({ error: "Name must be at least 2 characters" });
      }
      if (password !== confirmPassword) {
        return reply.status(400).send({ error: "Passwords don't match" });
      }

      // Use Better Auth's sign-up
      const response = await auth.handler(
        new Request(
          `http://${request.headers.host}/api/auth/sign-up`,
          {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ email, password, name }),
          }
        )
      );

      if (response.status === 200 || response.status === 201) {
        return reply.status(201).send({
          success: true,
          user: {
            email,
            name,
          },
          session: {
            expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
          },
        });
      } else {
        return reply.status(409).send({
          success: false,
          error: "User with this email already exists",
        });
      }
    } catch (error: unknown) {
      app.log.error("Error in custom-sign-up:", error);
      return reply.status(500).send({ 
        success: false,
        error: error instanceof Error ? error.message : "Sign up failed",
      });
    }
  }
});

/**
 * Better Auth Handler - Handles all standard auth endpoints
 * 
 * Routes all authentication requests to Better Auth:
 * - POST /api/auth/sign-up - Register new user
 * - POST /api/auth/sign-in - Login user
 * - POST /api/auth/sign-out - Logout user
 * - GET /api/auth/session - Get current session
 * - GET /api/auth/ok - Health check
 */
app.route({
  method: ["GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"],
  url: "/api/auth/*",
  async handler(request, reply) {
    try {
      const url = new URL(request.url, `http://${request.headers.host}`);

      const headers = fromNodeHeaders(request.headers);

      const req = new Request(url.toString(), {
        method: request.method,
        headers,
        ...(request.body ? { body: JSON.stringify(request.body) } : {}),
      });

      // Process authentication request with Better Auth
      const response = await auth.handler(req);

      // Forward response to client
      reply.status(response.status);
      response.headers.forEach((value, key) => reply.header(key, value));
      return reply.send(response.body ? await response.text() : null);
    } catch (error: unknown) {
      app.log.error("Authentication Error:", error);
      return reply.status(500).send({ 
        error: "Internal authentication error",
        code: "AUTH_FAILURE"
      });
    }
  }
})

const server = app.listen({ port: PORT, host: "0.0.0.0" }, (err, address) => {
  if (err) {
    app.log.error(err);
    process.exit(1);
  }
  app.log.info(`Server listening at ${address}`);
});

export { app, server };

