import Fastify, { type FastifyServerOptions, type FastifyInstance } from "fastify";
import autoLoad from "@fastify/autoload";
import { fileURLToPath } from "url";
import { dirname, join } from "path";
import {
  type ZodTypeProvider,
  serializerCompiler,
  validatorCompiler,
} from "fastify-type-provider-zod";
import fp from "fastify-plugin";
import fastifyCors from "@fastify/cors";
import { auth } from "./lib/auth";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// CORS configuration for frontend integration, allowing credentials and specific headers
// Adjust the origin as needed for production
const corsOptions = {
  origin: ["http://localhost:3000"], // Replace with your frontend URL
  methods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],
  allowedHeaders: ["Content-Type", "Authorization", "X-Requested-With"],
  credentials: true,
  maxAge: 86400, // Cache preflight response for 24 hours
};

// Plugin version for serverless deployment
async function fastifyServerPlugin(fastify: FastifyInstance) {
  // Set the validator and serializer compilers
  fastify.setValidatorCompiler(validatorCompiler);
  fastify.setSerializerCompiler(serializerCompiler);

  await fastify.register(fastifyCors, {
    origin: corsOptions.origin,
    methods: corsOptions.methods,
    allowedHeaders: corsOptions.allowedHeaders,
    credentials: corsOptions.credentials,
    maxAge: corsOptions.maxAge,
  });

  // Register custom auth endpoints BEFORE auto-loading routes
  await fastify.register(async (fastify) => {
    fastify.route({
      method: ["GET"],
      url: "/api/auth/get-session",
      async handler(request, reply) {
        try {
          // Get the session from Better Auth
          const session = await auth.api.getSession({ headers: Object.fromEntries(request.headers) });

          if (!session || !session.data || !session.data.user) {
            return reply.status(401).send({ error: "Not authenticated" });
          }

          return reply.status(200).send({
            session: session.data.session ? {
              id: session.data.session.id,
              userId: session.data.session.userId,
              expiresAt: session.data.session.expiresAt,
              createdAt: session.data.session.createdAt,
              updatedAt: session.data.session.updatedAt || new Date(),
            } : null,
            user: session.data.user ? {
              id: session.data.user.id,
              name: session.data.user.name,
              email: session.data.user.email,
              image: session.data.user.image || null,
              emailVerified: session.data.user.emailVerified || false,
              createdAt: session.data.user.createdAt,
              updatedAt: session.data.user.updatedAt || new Date(),
            } : null,
          });
        } catch (error: unknown) {
          fastify.log.error("Error in get-session:", error);
          return reply.status(500).send({ 
            error: error instanceof Error ? error.message : "Internal server error",
          });
        }
      }
    });

    fastify.route({
      method: ["POST"],
      url: "/api/auth/update-user",
      async handler(request, reply) {
        try {
          // Get the session
          const session = await auth.api.getSession({ headers: Object.fromEntries(request.headers) });

          if (!session || !session.data || !session.data.user) {
            return reply.status(401).send({ error: "Not authenticated" });
          }

          const body = request.body as Record<string, unknown> || {};
          const { name, email, image } = body;

          // Validate input
          if (typeof name !== "string" && name !== undefined) {
            return reply.status(400).send({ error: "Name must be a string" });
          }
          if (typeof email !== "string" && email !== undefined) {
            return reply.status(400).send({ error: "Email must be a string" });
          }
          if (typeof image !== "string" && image !== undefined && image !== null) {
            return reply.status(400).send({ error: "Image must be a string or null" });
          }

          // Update user using Better Auth API
          const updateData: Record<string, unknown> = {};
          if (name !== undefined) updateData.name = name;
          if (email !== undefined) updateData.email = email;
          if (image !== undefined) updateData.image = image;

          const result = await auth.api.updateUser({
            data: updateData,
            headers: Object.fromEntries(request.headers),
          });

          if (result && result.data && result.data.user) {
            return reply.status(200).send({
              success: true,
              user: {
                id: result.data.user.id,
                name: result.data.user.name,
                email: result.data.user.email,
                image: result.data.user.image || null,
                updatedAt: new Date(),
              },
            });
          } else {
            return reply.status(400).send({
              success: false,
              error: result?.error?.message || "Failed to update user",
            });
          }
        } catch (error: unknown) {
          fastify.log.error("Error in update-user:", error);
          return reply.status(400).send({ 
            error: error instanceof Error ? error.message : "Invalid request",
          });
        }
      }
    });

    fastify.route({
      method: ["POST"],
      url: "/api/auth/custom-sign-up",
      async handler(request, reply) {
        try {
          const body = request.body as Record<string, unknown> || {};
          const { email, password, name, confirmPassword } = body;

          fastify.log.info(`Received sign-up request:`, { email, name, hasPassword: !!password, hasConfirm: !!confirmPassword });

          // Validate input
          if (typeof email !== "string" || !email.includes("@")) {
            return reply.status(400).send({ error: "Invalid email" });
          }
          if (typeof password !== "string" || password.length < 8) {
            return reply.status(400).send({ error: "Password must be at least 8 characters" });
          }
          if (typeof name !== "string" || name.length < 2) {
            return reply.status(400).send({ error: "Name must be at least 2 characters" });
          }
          if (password !== confirmPassword) {
            return reply.status(400).send({ error: "Passwords don't match" });
          }

          // Use Better Auth's API to sign up
          const result = await auth.api.signUpEmail({
            email,
            password,
            name,
          });

          if (result && result.data && result.data.user) {
            // User created successfully
            return reply.status(201).send({
              success: true,
              user: {
                id: result.data.user.id,
                email: result.data.user.email,
                name: result.data.user.name,
              },
              session: result.data.session ? {
                id: result.data.session.id,
                expiresAt: new Date(result.data.session.expiresAt),
              } : null,
            });
          } else if (result && result.error) {
            // Error response from Better Auth
            return reply.status(400).send({
              success: false,
              error: result.error.message || "Sign up failed",
            });
          } else {
            return reply.status(500).send({
              success: false,
              error: "Sign up failed - unexpected response",
            });
          }
        } catch (error: unknown) {
          fastify.log.error("Error in custom-sign-up:", error);
          if (error instanceof Error && error.message.includes("duplicate")) {
            return reply.status(409).send({ 
              success: false,
              error: "User with this email already exists",
            });
          }
          return reply.status(500).send({ 
            success: false,
            error: error instanceof Error ? error.message : "Sign up failed",
          });
        }
      }
    });
  });

