      // Validate input
      if (typeof name !== "string" && name !== undefined) {
        return reply.status(400).send({ error: "Name must be a string" });
      }
      if (typeof email !== "string" && email !== undefined) {
        return reply.status(400).send({ error: "Email must be a string" });
      }
      if (typeof image !== "string" && image !== undefined && image !== null) {
        return reply.status(400).send({ error: "Image must be a string or null" });
      }

      // Update user using Better Auth API
      const updateData: Record<string, unknown> = {};
      if (name !== undefined) updateData.name = name;
      if (email !== undefined) updateData.email = email;
      if (image !== undefined) updateData.image = image;

      const result = await auth.api.updateUser({
        data: updateData,
        headers: Object.fromEntries(request.headers),
      });

      if (result && result.data && result.data.user) {
        return reply.status(200).send({
          success: true,
          user: {
            id: result.data.user.id,
            name: result.data.user.name,
            email: result.data.user.email,
            image: result.data.user.image || null,
            updatedAt: new Date(),
          },
        });
      } else {
        return reply.status(400).send({
          success: false,
          error: result?.error?.message || "Failed to update user",
        });
      }
    } catch (error: unknown) {
      app.log.error("Error in update-user:", error);
      return reply.status(400).send({ 
        error: error instanceof Error ? error.message : "Invalid request",
      });
    }
  }
});

app.route({
  method: ["POST"],
  url: "/api/auth/custom-sign-up",
  async handler(request, reply) {
    try {
      app.log.info(`Request body:`, request.body);
      app.log.info(`Request headers:`, request.headers);

      const body = request.body as Record<string, unknown> || {};
      const { email, password, name, confirmPassword } = body;

      // Validate input
      if (typeof email !== "string" || !email.includes("@")) {
        return reply.status(400).send({ error: "Invalid email" });
      }
      if (typeof password !== "string" || password.length < 8) {
        return reply.status(400).send({ error: "Password must be at least 8 characters" });
      }
      if (typeof name !== "string" || name.length < 2) {
        return reply.status(400).send({ error: "Name must be at least 2 characters" });
      }
      if (password !== confirmPassword) {
        return reply.status(400).send({ error: "Passwords don't match" });
      }

      // Use Better Auth's API to sign up
      const result = await auth.api.signUpEmail({
        email,
        password,
        name,
      });

      if (result && result.data && result.data.user) {
        // User created successfully
        return reply.status(201).send({
          success: true,
          user: {
            id: result.data.user.id,
            email: result.data.user.email,
            name: result.data.user.name,
          },
          session: result.data.session ? {
            id: result.data.session.id,
            expiresAt: new Date(result.data.session.expiresAt),
          } : null,
        });
      } else if (result && result.error) {
        // Error response from Better Auth
        return reply.status(400).send({
          success: false,
          error: result.error.message || "Sign up failed",
        });
      } else {
        return reply.status(500).send({
          success: false,
          error: "Sign up failed - unexpected response",
        });
      }
    } catch (error: unknown) {
      app.log.error("Error in custom-sign-up:", error);
      if (error instanceof Error && error.message.includes("duplicate")) {
        return reply.status(409).send({ 
          success: false,
          error: "User with this email already exists",
        });
      }
      return reply.status(500).send({ 
        success: false,
        error: error instanceof Error ? error.message : "Sign up failed",
      });
    }
  }
});

/**
 * Better Auth Handler - Handles all standard auth endpoints
 * 
 * Routes all authentication requests to Better Auth:
 * - POST /api/auth/sign-up - Register new user
 * - POST /api/auth/sign-in - Login user
 * - POST /api/auth/sign-out - Logout user
 * - GET /api/auth/session - Get current session
 * - GET /api/auth/ok - Health check
 */
app.route({
  method: ["GET", "POST", "PUT", "DELETE", "PATCH", "HEAD", "OPTIONS"],
  url: "/api/auth/*",
  async handler(request, reply) {
    try {
      const url = new URL(request.url, `http://${request.headers.host}`);

      const headers = fromNodeHeaders(request.headers);

      const req = new Request(url.toString(), {
        method: request.method,
        headers,
        ...(request.body ? { body: JSON.stringify(request.body) } : {}),
      });

      // Process authentication request with Better Auth
      const response = await auth.handler(req);

      // Forward response to client
      reply.status(response.status);
      response.headers.forEach((value, key) => reply.header(key, value));
      return reply.send(response.body ? await response.text() : null);
    } catch (error: unknown) {
      app.log.error("Authentication Error:", error);
      return reply.status(500).send({ 
        error: "Internal authentication error",
        code: "AUTH_FAILURE"
      });
    }
  }
})

const server = app.listen({ port: PORT, host: "0.0.0.0" }, (err, address) => {
  if (err) {
    app.log.error(err);
    process.exit(1);
  }
  app.log.info(`Server listening at ${address}`);
});

export { app, server };

