fastify.route({
  method: ["POST"],
  url: "/api/auth/custom-sign-up",
  async handler(request, reply) {
    try {
      fastify.log.info(`Request body type:`, typeof request.body);
      fastify.log.info(`Request body:`, request.body);

      const body = (request.body as unknown) || {};
      fastify.log.info(`Parsed body:`, body);

      const bodyObj = body as Record<string, unknown>;
      const { email, password, name, confirmPassword } = bodyObj;

      fastify.log.info(`Extracted fields:`, { email, password: !!password, name, confirmPassword: !!confirmPassword });

      // Validate input
      if (typeof email !== "string" || !email.includes("@")) {
        return reply.status(400).send({ error: "Invalid email" });
      }
      if (typeof password !== "string" || password.length < 8) {
        return reply.status(400).send({ error: "Password must be at least 8 characters" });
      }
      if (typeof name !== "string" || name.length < 2) {
        return reply.status(400).send({ error: "Name must be at least 2 characters" });
      }
      if (password !== confirmPassword) {
        return reply.status(400).send({ error: "Passwords don't match" });
      }

      fastify.log.info(`All validation passed, attempting sign-up...`);

      // Use Better Auth's API to sign up
      const result = await auth.api.signUpEmail({
        email,
        password,
        name,
      });

      fastify.log.info(`Sign-up result:`, result);

      if (result && result.data && result.data.user) {
        // User created successfully
        return reply.status(201).send({
          success: true,
          user: {
            id: result.data.user.id,
            email: result.data.user.email,
            name: result.data.user.name,
          },
          session: result.data.session ? {
            id: result.data.session.id,
            expiresAt: new Date(result.data.session.expiresAt),
          } : null,
        });
      } else if (result && result.error) {
        // Error response from Better Auth
        return reply.status(400).send({
          success: false,
          error: result.error.message || "Sign up failed",
        });
      } else {
        return reply.status(500).send({
          success: false,
          error: "Sign up failed - unexpected response",
        });
      }
    } catch (error: unknown) {
      fastify.log.error("Full error stack:", error instanceof Error ? error.stack : String(error));
      fastify.log.error("Error message:", error instanceof Error ? error.message : String(error));

      if (error instanceof Error && error.message.includes("duplicate")) {
        return reply.status(409).send({ 
          success: false,
          error: "User with this email already exists",
        });
      }
      return reply.status(500).send({ 
        success: false,
        error: error instanceof Error ? error.message : "Sign up failed",
      });
    }
  }
});

